mapper.update:
/* com.portal.user.poll.qri.QustnrRespondInfoMapper.updateQustnrRespondInfo */
UPDATE LETTNQUSTNRRSPNSRESULT
SET
	QUSTNR_IEM_ID      = #{qustnrIemId},
	RESPOND_ANSWER_CN  = #{respondAnswerCn},
	RESPOND_NM         = #{respondNm},
	ETC_ANSWER_CN      = #{etcAnswerCn},
	LAST_UPDT_PNTTM    = sysdate(),
	LAST_UPDUSR_ID     = #{lastUpdusrId}
WHERE QUSTNR_RSPNS_RESULT_ID = #{qestnrQesrspnsId}

mapper.select:
/* com.portal.user.poll.qri.QustnrRespondInfoMapper.selectQustnrRespondInfoManageList */ SELECT A.QESTNR_ID, A.QUSTNR_SJ AS qestnrSj, A.QUSTNR_PURPS AS qestnrPurps, A.QUSTNR_WRITNG_GUIDANCE_CN AS qestnrWritngGuidanceCn, DATE_FORMAT(A.QUSTNR_BGNDE, '%Y-%m-%d') AS qestnrBeginDe, DATE_FORMAT(A.QUSTNR_ENDDE, '%Y-%m-%d') AS qestnrEndDe, A.QUSTNR_TRGET AS qestnrTrget, A.QUSTNR_TMPLAT_ID AS qestnrTmplatId, DATE_FORMAT(A.FRST_REGIST_PNTTM, '%Y-%m-%d') AS FRST_REGIST_PNTTM, A.FRST_REGISTER_ID, B.USER_NM AS FRST_REGISTER_NM, DATE_FORMAT(A.LAST_UPDT_PNTTM, '%Y-%m-%d') AS LAST_UPDT_PNTTM, A.LAST_UPDUSR_ID FROM LETTNQESTNRINFO A INNER JOIN COMVNUSERMASTER B ON A.FRST_REGISTER_ID = B.ESNTL_ID WHERE 1=1
AND A.QUSTNR_SJ LIKE CONCAT('%', #{searchKeyword}, '%')
AND B.USER_NM LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY A.FRST_REGIST_PNTTM DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

/* com.portal.user.poll.qri.QustnrRespondInfoMapper.selectQustnrRespondInfoManageListCnt */ SELECT COUNT(*) AS totcnt FROM LETTNQESTNRINFO A INNER JOIN COMVNUSERMASTER B ON A.FRST_REGISTER_ID = B.ESNTL_ID WHERE 1=1
AND A.QUSTNR_SJ LIKE CONCAT('%', #{searchKeyword}, '%')
AND B.USER_NM LIKE CONCAT('%', #{searchKeyword}, '%')

/* com.portal.user.poll.qri.QustnrRespondInfoMapper.selectQustnrRespondInfoList */ SELECT A.QUSTNR_RSPNS_RESULT_ID AS qestnrQesrspnsId, ( SELECT QESTN_TY_CODE FROM LETTNQUSTNRQESITM WHERE QUSTNR_QESITM_ID = A.QUSTNR_QESITM_ID ) AS QESTN_TY_CODE, ( SELECT QESTN_CN FROM LETTNQUSTNRQESITM WHERE QUSTNR_QESITM_ID = A.QUSTNR_QESITM_ID ) AS QESTN_CN, ( SELECT IEM_CN FROM LETTNQUSTNRIEM WHERE QUSTNR_IEM_ID = A.QUSTNR_IEM_ID ) AS IEM_CN, A.QUSTNR_IEM_ID, A.QUSTNR_QESITM_ID AS qestnrQesitmId, A.QESTNR_ID, A.RESPOND_ANSWER_CN, A.RESPOND_NM, A.ETC_ANSWER_CN, A.QUSTNR_TMPLAT_ID AS qestnrTmplatId, DATE_FORMAT(A.FRST_REGIST_PNTTM, '%Y-%m-%d') AS FRST_REGIST_PNTTM, A.FRST_REGISTER_ID, (SELECT USER_NM FROM COMVNUSERMASTER WHERE ESNTL_ID = A.FRST_REGISTER_ID) AS FRST_REGISTER_NM, DATE_FORMAT(A.LAST_UPDT_PNTTM, '%Y-%m-%d') AS LAST_UPDT_PNTTM, A.LAST_UPDUSR_ID FROM LETTNQUSTNRRSPNSRESULT A WHERE 1=1
AND A.ETC_ANSWER_CN LIKE CONCAT('%', #{searchKeyword}, '%')
AND A.RESPOND_ANSWER_CN LIKE CONCAT('%', #{searchKeyword}, '%')
AND A.RESPOND_NM LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY A.FRST_REGIST_PNTTM DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}
